// authz_check.go — 演示网关粗鉴权 + 业务层对象级校验 + step-up 认证
package authz

import (
	"context"
	"errors"
	"time"
)

type IdentityContext struct {
	Subject string
	Tenant  string
	Roles   []string
	AAL     int       // 认证强度: 1=单因子, 2=MFA
	JTI     string
	Exp     time.Time
}

type Order struct {
	ID     string
	Tenant string
	Owner  string
	Status string // draft, submitted, archived
}

// Step 1: 网关粗粒度 RBAC — 只检查角色是否允许访问该路由
cfunc GatewayAuthz(identity IdentityContext, requiredRole string) error {
	if time.Now().After(identity.Exp) {
		return errors.New("token expired")
	}
	hasRole := false
	for _, r := range identity.Roles {
		if r == requiredRole {
			hasRole = true
			break
		}
	}
	if !hasRole {
		return errors.New("gateway RBAC deny: missing role " + requiredRole)
	}
	return nil
}

// Step 2: 业务层对象级校验 — tenant + owner + 状态 + step-up
func OrderServiceAuthz(identity IdentityContext, order Order, action string) error {
	// 租户隔离
	if identity.Tenant != order.Tenant {
		return errors.New("tenant mismatch: cross-tenant access denied")
	}
	// 对象 owner 校验 (水平越权防护)
	if action == "read" || action == "update" {
		if identity.Subject != order.Owner {
			return errors.New("owner mismatch: horizontal privilege escalation denied")
		}
	}
	// 垂直越权: delete 只允许 admin
	if action == "delete" {
		isAdmin := false
		for _, r := range identity.Roles {
			if r == "admin" {
				isAdmin = true
				break
			}
		}
		if !isAdmin {
			return errors.New("vertical escalation: non-admin cannot delete")
		}
	}
	// 状态校验: archived 订单不可修改
	if action == "update" && order.Status == "archived" {
		return errors.New("state deny: archived order is read-only")
	}
	// Step-up: 敏感操作要求 aal2
	if action == "delete" && identity.AAL < 2 {
		return errors.New("step-up required: delete needs MFA (aal2)")
	}
	return nil
}

// Step 3: 一次请求的完整鉴权流程
func HandleOrderRequest(ctx context.Context, identity IdentityContext, order Order, action string) error {
	// 网关: 粗粒度 RBAC
	if err := GatewayAuthz(identity, "order_user"); err != nil {
		return err // 403
	}
	// 业务层: 对象级校验
	if err := OrderServiceAuthz(identity, order, action); err != nil {
		return err // 403
	}
	// 授权通过，执行业务逻辑
	return nil
}
